/**
 * The notice's artwork: the user's illustration, packaged as the layers the
 * notice animates. Nothing here is drawn — the scene, the whale, the spray, and
 * the water that hides the submerged whale are the artwork's own pixels, and
 * each layer's box is a percentage of the 1448x1086 scene it was measured in,
 * so the composite is the artwork's own composition.
 *
 * Every layer is a WebP data URL: the client bundle carries them, so serving
 * the notice needs no separate asset request.
 */

/** Scene box the layers are positioned inside, in CSS pixels. */
export const ART_SCENE = { width: 420, height: 315 } as const

/** One positioned layer: the image plus its box inside the scene. */
export interface ArtLayer {
  /** Layer image as a data URL. */
  readonly src: string
  /** Left edge as a percent of the scene width. */
  readonly left: number
  /** Top edge as a percent of the scene height. */
  readonly top: number
  /** Width as a percent of the scene width. */
  readonly width: number
}

